import{_ as e,o as s,c as t,a2 as i}from"./chunks/framework.CTx8wfac.js";const g=JSON.parse('{"title":"AI module generation","description":"","frontmatter":{},"headers":[],"relativePath":"tooling/ai-module-generation.md","filePath":"tooling/ai-module-generation.md"}'),n={name:"tooling/ai-module-generation.md"};function o(r,a,l,d,h,p){return s(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="ai-module-generation" tabindex="-1">AI module generation <a class="header-anchor" href="#ai-module-generation" aria-label="Permalink to &quot;AI module generation&quot;">​</a></h1><p>This guide covers <strong><code>bananajs ai setup</code></strong>, <strong><code>.bananarc.json</code></strong>, and <strong><code>bananajs ai generate --module</code></strong> — offline-first LLM providers (Ollama default) plus optional cloud models, and a two-step pipeline: <strong>LLM → JSON (validated with Zod) → DDD templates</strong>.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li><strong>BananaJS CLI</strong> (<code>@banana-universe/bananajs-cli</code>) installed in your project or globally.</li><li>For <strong>local</strong> generation: <a href="https://ollama.com" target="_blank" rel="noreferrer">Ollama</a> running (<code>ollama serve</code>) and a model pulled (e.g. <code>ollama pull llama3.2</code>).</li><li>Optional: <strong><code>zod</code></strong> for JSON validation of the extraction step (recommended; listed as an optional peer of the CLI).</li></ul><h2 id="_1-configure-the-cli-bananajs-ai-setup" tabindex="-1">1. Configure the CLI: <code>bananajs ai setup</code> <a class="header-anchor" href="#_1-configure-the-cli-bananajs-ai-setup" aria-label="Permalink to &quot;1. Configure the CLI: \`bananajs ai setup\`&quot;">​</a></h2><p>Run from your app root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bananajs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ai</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span></span></code></pre></div><p>The wizard lets you pick:</p><table tabindex="0"><thead><tr><th>Provider</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Ollama</strong></td><td>Default; no API keys; uses <code>llm.baseUrl</code> (default <code>http://localhost:11434</code>)</td></tr><tr><td><strong>llama.cpp</strong></td><td>HTTP server mode (e.g. <code>/completion</code> on port 8080)</td></tr><tr><td><strong>OpenAI</strong></td><td>Requires <code>OPENAI_API_KEY</code></td></tr><tr><td><strong>Anthropic</strong></td><td>Requires <code>ANTHROPIC_API_KEY</code></td></tr></tbody></table><p>The command writes <strong><code>.bananarc.json</code></strong> at the project root, for example:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;llm&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;provider&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ollama&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;model&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;llama3.2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;baseUrl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://localhost:11434&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;retries&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;timeoutMs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">30000</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;generate&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;defaultOrm&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;typeorm&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;outDir&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./src&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>.bananarc.json</code> is the <strong>general BananaJS project config</strong>: the <code>llm</code> block holds provider settings; <code>generate</code> holds defaults for <code>bananajs ai generate --module</code> (ORM and output directory).</p><h2 id="_2-generate-a-full-ddd-module" tabindex="-1">2. Generate a full DDD module <a class="header-anchor" href="#_2-generate-a-full-ddd-module" aria-label="Permalink to &quot;2. Generate a full DDD module&quot;">​</a></h2><h3 id="from-natural-language" tabindex="-1">From natural language <a class="header-anchor" href="#from-natural-language" aria-label="Permalink to &quot;From natural language&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bananajs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ai</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> generate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Product catalog with name, price, category, and stock quantity&quot;</span></span></code></pre></div><p>The CLI:</p><ol><li>Calls the configured LLM with a <strong>strict JSON extraction</strong> prompt (entity name + fields).</li><li>Parses and validates the response with <strong>Zod</strong> (<code>EntityExtractionSchema</code>); on failure it <strong>retries once</strong> (then exits with a clear error; use <strong><code>--debug</code></strong> to print raw LLM output).</li><li>Fills <strong>embedded templates</strong> for the standard DDD layout: <code>domain/</code>, <code>application/</code>, <code>infrastructure/</code>, and controller.</li></ol><h3 id="from-json-schema-or-openapi" tabindex="-1">From JSON Schema or OpenAPI <a class="header-anchor" href="#from-json-schema-or-openapi" aria-label="Permalink to &quot;From JSON Schema or OpenAPI&quot;">​</a></h3><p>Use <strong><code>--module</code></strong> together with <strong><code>--from-schema</code></strong> so the schema drives the entity shape (no LLM extraction step):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bananajs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ai</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> generate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --module</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from-schema</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./openapi/product.yaml</span></span></code></pre></div><p>You can pass a bare <strong><code>--module</code></strong> flag when only the schema is needed (the description is optional if the schema is present).</p><h3 id="orm-and-output" tabindex="-1">ORM and output <a class="header-anchor" href="#orm-and-output" aria-label="Permalink to &quot;ORM and output&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>Purpose</th></tr></thead><tbody><tr><td><strong><code>--orm</code></strong></td><td><code>typeorm</code> | <code>mongoose</code> | <code>none</code> (overrides <code>generate.defaultOrm</code>)</td></tr><tr><td><strong><code>--out</code></strong></td><td>Base directory for generated files (default: <code>generate.outDir</code> in <code>.bananarc.json</code>)</td></tr><tr><td><strong><code>--dry-run</code></strong></td><td>Print files without writing</td></tr><tr><td><strong><code>--detailed</code></strong></td><td>Optional second LLM pass to expand domain/application service bodies</td></tr><tr><td><strong><code>--debug</code></strong></td><td>Log raw extraction output and validation retries</td></tr></tbody></table><h2 id="_3-flat-scaffold-unchanged" tabindex="-1">3. Flat scaffold (unchanged) <a class="header-anchor" href="#_3-flat-scaffold-unchanged" aria-label="Permalink to &quot;3. Flat scaffold (unchanged)&quot;">​</a></h2><p>Without <strong><code>--module</code></strong>, behavior stays as before:</p><ul><li><strong><code>--from-schema</code></strong> — deterministic flat controller + DTO + service (no DDD folders).</li><li><strong><code>--from-prompt</code></strong> — same three <strong>flat</strong> files via the configured LLM (not only OpenAI).</li></ul><h2 id="_4-error-messages-and-tuning" tabindex="-1">4. Error messages and tuning <a class="header-anchor" href="#_4-error-messages-and-tuning" aria-label="Permalink to &quot;4. Error messages and tuning&quot;">​</a></h2><ul><li><strong>Ollama unreachable</strong> — ensure Ollama is running (<code>ollama serve</code>).</li><li><strong>Unparseable JSON</strong> — use <strong><code>--debug</code></strong>; increase <strong><code>llm.retries</code></strong> or <strong><code>llm.timeoutMs</code></strong> in <code>.bananarc.json</code> if the model is slow.</li><li><strong>Timeouts</strong> — see <code>llm.timeoutMs</code> (default 30s).</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/banana-universe/tooling/cli.html">CLI reference</a></li><li><a href="/banana-universe/tooling/ai-commands.html">AI commands overview</a></li><li><a href="/banana-universe/guide/layered-architecture.html">Layered architecture (DDD)</a></li></ul>`,30)])])}const u=e(n,[["render",o]]);export{g as __pageData,u as default};
